WFJ.Data.add("gossip", {
  ["18076c900eb61931"] = { "Elune ha concesso molti doni agli elfi della notte. In cambio, abbiamo il compito di proteggere queste foreste dalla corruzione demoniaca che l'⟦Horde=Orda⟧ porta sempre con sé.", "." },
  ["1809700f2b1d207d"] = { "Avete sconfitto i miei servitori? Allora affrontatemi, mortali!", "." },
  ["180990cb69ea7a3b"] = { "%s getta le parti di animale nel calderone ribollente.", "." },
  ["180da3a470cf32f9"] = { "Le tue conoscenze sono scarse. Torna da me quando le tue abilità nella fusione saranno cresciute!", "." },
  ["18149e1fc7e00e8f"] = { "Nel cielo notturno è all'opera qualcosa di più grande della magia. Un giorno mi daranno ascolto. . . .", "." },
  ["18160e83b09095cc"] = { "Ben detto! Ben detto! Ci brindo sopra!", "." },
  ["1817445ecf622ad3"] = { "L'anziano Rumblerock trascorre gli anni in una grotta in cima al ⟦Dreadmaul Rock=Masso dei Maglioinfame⟧, nelle ⟦Burning Steppes=Steppe Ardenti⟧.", "." },
  ["181d53c11c8989d4"] = { "Cosa desideri, <signore/signorina>?", "." },
  ["181f4453cd447e7c"] = { "In ginocchio, infedele.", "." },
  ["181f95a72db5ea87"] = { "%s annuisce con aria d'intesa.", "." },
  ["182990b13702825b"] = { "Ora mettiamo alla prova il mio progetto!", "." },
  ["183305478ce2066f"] = { "Zug zug! Felice di aiutare!", "." },
  ["183ce490fbae0e8a"] = { "Tremate di paura, cani! Sono qui!", "." },
  ["183d521fc1dd3fc7"] = { "Non avevo scelta, o così credevo. Avrei sopportato la distruzione di Thaurissan e avrei continuato a stare al fianco del mio re e del suo popolo.\n\nSotto il controllo di Ragnaros, re Dagran Thaurissan strappò il cuore di questa montagna ed eresse i ⟦Blackrock Spire=Bastioni di Roccianera⟧. Lavorammo senza sosta per costruire una città nanica più potente di qualsiasi città o fortezza venuta prima... o che sarebbe venuta dopo.", "." },
  ["183f5f873a0e9351"] = { "Salute, amici, e benvenuti al più grande spettacolo di Azeroth!\n\nPrego, fatevi avanti e godetevi tutto ciò che abbiamo da offrire. Salite sulle giostre e ammirate le attrazioni! Stupitevi delle meraviglie che la ⟦Darkmoon Faire=Fiera di Lunacupa⟧ ha scoperto in questo mondo vasto e misterioso! Non abbiamo badato a spese per offrirvi emozioni che faranno la gioia di bambini di tutte le età!", "." },
  ["18490e97868b7520"] = { "C'è chi può insegnarti l'Erbalismo nella grande casa di ⟦Thunder Bluff=Picco del Tuono⟧, lontano a nord. Per arrivarci segui la strada che esce dal villaggio e, ai piedi del picco, prendi l'ascensore fino in cima all'altura. Lassù ci sono molti Guardiani del Picco che sapranno indicarti la strada.", "." },
  ["1850cdbc59808e13"] = { "Eccellente... a quanto pare gli insetti impiccioni sono arrivati giusto in tempo per sfamare la mia legione. Benvenuti, mortali!", "." },
  ["1854f1fa6ece625d"] = { "Athrikus Narassin è uno stregone antico e potente. Forse dovremmo aspettare l'aiuto di Delgren, ma evidentemente aveva molta fiducia in te, per mandarti da sol<o/a>.", "." },
  ["185b0da5fc262897"] = { "La mia morte non significa nulla.... la Luce... prevarrà!", "." },
  ["185b6b435893f088"] = { "Sei tu, mio caro Tobias???", "." },
  ["1864902635b24b32"] = { "I fili della VITA sono stati recisi! I Sognatori devono essere vendicati!", "." },
  ["18687350c2ad7d5d"] = { "Come sarebbe, comprare?! Adesso il re sono io... ed è bello essere il re!", "." },
  ["186fd1b3c0fd28d9"] = { "Oh, aspetta! Dovrei cercare quel fossile misterioso!", "." },
  ["1871421fd99f5cc2"] = { "Un altro cuoco a Dolanaar ci farebbe davvero comodo, non che la cucina di Zarrin abbia qualcosa che non va, bada bene. Perché non vai a vedere cosa può insegnarti?", "." },
  ["1872476dc2570f59"] = { "Intrusi! Attaccate gli intrusi!", "." },
  ["188045859b8d5aba"] = { "Sono in salvo.", "." },
  ["1886c61786c2ce13"] = { "Salve, {class}. Spero che tu sia qui per rinforzare le nostre file. Bestie e ladri stanno invadendo la nostra amata Elwynn, e abbiamo a malapena gli uomini per tenere sicure le strade!\n\nE se non l'hai ancora fatto, leggi quell'avviso su ⟦Hogger=Boccalarga⟧. È una bestia che si aggira in quei boschi laggiù e di cui bisogna occuparsi.", "." },
  ["18890b157610edb1"] = { "Perché scappi da me, ⟦Fluffy=Morbidino⟧!", "." },
  ["188a2dc1369726b4"] = { "Gli Dei Antichi torneranno al potere. Non ti sarà permesso di interferire!", "." },
  ["188e9130c0a2e877"] = { "Anu therador mali {class}. Dove posso guidarti?", "." },
  ["1891f964e2b192a6"] = { "Capitolo sui Cristalli Arcani e l'arcanite.", "." },
  ["18a307ae9775aedf"] = { "%s si china per esaminare il suo colpo.", "." },
  ["18b7ed96c13d58c9"] = { "{name}, che bello rivederti! Ti stai divertendo alla Fiera?\n\nVuoi fare a braccio di ferro? No, certo che no... ci tieni al tuo braccio!", "." },
  ["18bc5c8b86bc90dc"] = { "Già... Dammi le notizie.", "." },
  ["18bf4d2f3b414839"] = { "Quelli come te?", "." },
  ["18c13ed80e1ecc8d"] = { "Di nuovo? Sbrigati, Komak, ne ho fin sopra i capelli.", "." },
  ["18ca933e898a738e"] = { "E anche <modesto/modesta>... Forse allora è giunto il tuo momento, {name}.\n\nTe la senti di entrare nella fortezza degli orchi ⟦Blackrock=Roccianera⟧? Di seminare il caos? Di squarciare le fondamenta della cittadella della montagna?", "." },
  ["18d53a48e40eb090"] = { "Certo che posso mostrarti dov'è Myolor. Proprio laggiù, vicino all'incudine della ⟦Great Forge=Grande Forgia⟧: è lì che lavora. Ascolta bene le sue parole, <ragazzo/ragazza>: Myolor è abile come pochi.", "." },
  ["18d8206617b5c3be"] = { "Bada a dove metti i piedi, <straniero/straniera>. Non permettiamo ai malfattori di entrare nel nostro villaggio.", "." },
  ["18e3b042ce6e1012"] = { "Dove vuoi andare, <ragazzo/ragazza>? Per poche monete i miei grifoni ti ci portano più in fretta del più veloce dei cavalli.", "." },
  ["18ea7bd18677ec11"] = { "Salute, {name}! Hai fatto bene a venire da me. Siamo pronti a lanciare un assalto via terra attraverso il ⟦Field of Strife=Pian della Discordia⟧! Appena il maestro di guerra Garrick avrà i suoi ordini, lui e i suoi predoni si apriranno un varco tra l'⟦Alliance=Alleanza⟧!\n\nVuoi consegnare tu quegli ordini, {name}? Garrick aspetta nel ⟦Field of Strife=Pian della Discordia⟧...", "." },
  ["18f5939ab189813c"] = { "Ora inizio la tonaca...", "." },
  ["18fc5abbb7eaf0f4"] = { "Lo giuro, c'è gente che li ha visti davvero. I pandaren esistono sul serio!", "." },
